import{c as e,S as a,j as l,m as r}from"./chunks/framework.8aa1YH_s.js";const h=JSON.parse('{"title":"Türk Dil Bilgisi Serisi - 10: Şekil Bilgisi - İsim Çekim Ekleri","description":"","frontmatter":{},"headers":[],"relativePath":"10 Şekil Bilgisi - İsim Çekim Ekleri.md","filePath":"10 Şekil Bilgisi - İsim Çekim Ekleri.md"}'),n={name:"10 Şekil Bilgisi - İsim Çekim Ekleri.md"};function m(k,i,t,s,o,d){return a(),l("div",null,[...i[0]||(i[0]=[r('<h1 id="turk-dil-bilgisi-serisi-10-sekil-bilgisi-isim-cekim-ekleri" tabindex="-1">Türk Dil Bilgisi Serisi - 10: Şekil Bilgisi - İsim Çekim Ekleri <a class="header-anchor" href="#turk-dil-bilgisi-serisi-10-sekil-bilgisi-isim-cekim-ekleri" aria-label="Permalink to “Türk Dil Bilgisi Serisi - 10: Şekil Bilgisi - İsim Çekim Ekleri”">​</a></h1><p>Yapım ekleri ile kelime köklerinden yepyeni gövdeler türetmeyi öğrenmiştik. Bu yazımızda ise türemiş veya kök halindeki isimlerin cümle içinde görev almasını, diğer kelimelerle ilişki kurmasını sağlayan <strong>İsim Çekim Eklerini</strong> ele alıyoruz.</p><p>Prof. Dr. Muharrem Ergin&#39;e göre çekim ekleri, kelimelerin anlamını sabitleyen ama onlara fonksiyon kazandıran işletme çarklarıdır. İsim çekim ekleri, eklendikleri isimlerin anlamlarını değiştirmezler; onları zamana, mekana, şahsa ve mülkiyete bağlarlar.</p><p>Muharrem Ergin sistematiğinde isim çekim ekleri <strong>4 ana grupta</strong> incelenir:</p><hr><h2 id="_1-cokluk-cogul-eki" tabindex="-1">1. Çokluk (Çoğul) Eki <a class="header-anchor" href="#_1-cokluk-cogul-eki" aria-label="Permalink to “1. Çokluk (Çoğul) Eki”">​</a></h2><p>Türkçede isimlerin sayıca birden fazla olduğunu belirten ektir. Büyük ünlü uyumuna göre iki şekillidir: <strong><code>-lar / -ler</code></strong>.</p><ul><li><em>Örnekler:</em> <em>Ev-ler, taş-lar, göz-ler, kitap-lar...</em></li></ul><blockquote><p><strong>Not:</strong> Çoğul eki cümleye sadece &quot;birden fazla olma&quot; anlamı katmaz; abartma (<em>dünyalar kadar</em>), aile (<em>Aliler bize gelecek</em>), saygı/alay (<em>Müdür Beyler henüz gelmediler</em>) veya yaş/dönem (<em>yirmilerinde bir genç</em>) gibi çok farklı anlam ilgileri de kazandırabilir.</p></blockquote><hr><h2 id="_2-iyelik-sahiplik-aitlik-ekleri" tabindex="-1">2. İyelik (Sahiplik / Aitlik) Ekleri <a class="header-anchor" href="#_2-iyelik-sahiplik-aitlik-ekleri" aria-label="Permalink to “2. İyelik (Sahiplik / Aitlik) Ekleri”">​</a></h2><p>Bir nesnenin, varlığın veya kavramın kime, hangi şahsa ait olduğunu bildiren eklerdir. Türkçede 6 şahsa göre şekillenirler ve ünlü uyumlarına göre dört şekilli (<code>-ı, -i, -u, -ü</code>) halini alırlar.</p><ul><li><strong>1. Tekil Şahıs (Benim):</strong> <code>-m, -ım, -im, -um, -üm</code> $$\\rightarrow$$ <em>Kitab-ım, ev-im</em></li><li><strong>2. Tekil Şahıs (Senin):</strong> <code>-n, -ın, -in, -un, -ün</code> $$\\rightarrow$$ <em>Kitab-ın, ev-in</em></li><li><strong>3. Tekil Şahıs (Onun):</strong> <code>-ı, -i, -u, -ü / -sı, -si, -su, -sü</code> $$\\rightarrow$$ <em>Kitab-ı, ev-i, araba-sı</em></li><li><strong>1. Çoğul Şahıs (Bizim):</strong> <code>-mız, -miz, -muz, -müz</code> $$\\rightarrow$$ <em>Kitab-ımız, ev-imiz</em></li><li><strong>2. Çoğul Şahıs (Sizin):</strong> <code>-nız, -niz, -nuz, -nüz</code> $$\\rightarrow$$ <em>Kitab-ınız, ev-iniz</em></li><li><strong>3. Çoğul Şahıs (Onların):</strong> <code>-ları, -leri</code> $$\\rightarrow$$ <em>Kitap-ları, ev-leri</em></li></ul><hr><h2 id="_3-isim-hal-durum-ekleri-kelimeleri-cumleye-baglayan-guc" tabindex="-1">3. İsim Hal (Durum) Ekleri (Kelimeleri Cümleye Bağlayan Güç) <a class="header-anchor" href="#_3-isim-hal-durum-ekleri-kelimeleri-cumleye-baglayan-guc" aria-label="Permalink to “3. İsim Hal (Durum) Ekleri (Kelimeleri Cümleye Bağlayan Güç)”">​</a></h2><p>İsimleri fiillere, edatlara veya diğer isimlere bağlayan, cümledeki yüklemin o isme nasıl etki ettiğini gösteren eklerdir. Muharrem Ergin bu ekleri şu şekilde tasnif eder:</p><h3 id="a-yalın-hal-nominatif" tabindex="-1">A) Yalın Hal (Nominatif) <a class="header-anchor" href="#a-yalın-hal-nominatif" aria-label="Permalink to “A) Yalın Hal (Nominatif)”">​</a></h3><p>Kelimenin hiçbir hal eki almamış durumudur. (Çoğul veya iyelik eki alması yalınlığını bozmaz).</p><ul><li><em>Örnek:</em> <em>Ev, kitaplar, gözüm.</em></li></ul><h3 id="b-belirtme-yukleme-hali-akuzatif" tabindex="-1">B) Belirtme (Yükleme) Hali (Akuzatif) <a class="header-anchor" href="#b-belirtme-yukleme-hali-akuzatif" aria-label="Permalink to “B) Belirtme (Yükleme) Hali (Akuzatif)”">​</a></h3><p>Fiildeki hareketten doğrudan etkilenen varlığı belirtir. Eki: <strong><code>-ı, -i, -u, -ü</code></strong> (Neyi? Kimi? sorularına cevap verir).</p><ul><li><em>Örnek:</em> <em>Ev-i</em> gördüm. <em>Kitab-ı</em> okudum.</li></ul><h3 id="c-yonelme-yaklasma-hali-datif" tabindex="-1">C) Yönelme (Yaklaşma) Hali (Datif) <a class="header-anchor" href="#c-yonelme-yaklasma-hali-datif" aria-label="Permalink to “C) Yönelme (Yaklaşma) Hali (Datif)”">​</a></h3><p>Eylemin yöneldiği, yaklaştığı yeri veya hedefi bildirir. Eki: <strong><code>-a / -e</code></strong> (Nereye? Kime?).</p><ul><li><em>Örnek:</em> <em>Ev-e</em> gidiyorum. <em>Okul-a</em> baktım.</li></ul><h3 id="d-bulunma-hali-lokatif" tabindex="-1">D) Bulunma Hali (Lokatif) <a class="header-anchor" href="#d-bulunma-hali-lokatif" aria-label="Permalink to “D) Bulunma Hali (Lokatif)”">​</a></h3><p>Eylemin gerçekleştiği yeri, mekanı veya zamanı bildirir. Eki: <strong><code>-da / -de / -ta / -te</code></strong> (Nerede? Kimde?).</p><ul><li><em>Örnek:</em> <em>Ev-de</em> kaldım. <em>Sınıf-ta</em> bekliyor.</li></ul><h3 id="e-ayrılma-uzaklasma-hali-ablatif" tabindex="-1">E) Ayrılma (Uzaklaşma) Hali (Ablatif) <a class="header-anchor" href="#e-ayrılma-uzaklasma-hali-ablatif" aria-label="Permalink to “E) Ayrılma (Uzaklaşma) Hali (Ablatif)”">​</a></h3><p>Eylemin başlangıç noktasını, çıkış yerini veya sebebini bildirir. Eki: <strong><code>-dan / -den / -tan / -ten</code></strong> (Nereden? Kimden?).</p><ul><li><em>Örnek:</em> <em>Ev-den</em> çıktım. <em>Sıkıntı-dan</em> patladım.</li></ul><hr><h2 id="_4-ilgi-tamlayarak-genitif-eki" tabindex="-1">4. İlgi (Tamlayarak / Genitif) Eki <a class="header-anchor" href="#_4-ilgi-tamlayarak-genitif-eki" aria-label="Permalink to “4. İlgi (Tamlayarak / Genitif) Eki”">​</a></h2><p>Bir isimle başka bir isim arasında sahiplik veya aitlik ilişkisi kurarak <strong>İsim Tamlaması</strong> yapmamızı sağlayan ektir. Eki: <strong><code>-ın, -in, -un, -ün / -nın, -nin, -nun, -nün</code></strong> dür.</p><ul><li><em>Örnek:</em> <em>Kapı-nın</em> kolu, <em>ev-in</em> boyası, <em>çocuğ-un</em> kitabı.</li></ul><hr><h2 id="ozet" tabindex="-1">Özet <a class="header-anchor" href="#ozet" aria-label="Permalink to “Özet”">​</a></h2><p>Prof. Dr. Muharrem Ergin’in sistematiğinde isim çekim ekleri, bir cümlenin iskeletidir. Eğer bu ekler olmasaydı kelimeler yan yana yığılmış taşlar gibi hareketsiz kalırdı. Hal ekleri, iyelik ekleri ve ilgi ekleri sayesinde kelimeler birbiriyle konuşmaya, birbirine bağlanmaya başlar ve böylece düşüncelerimizi aktardığımız o muazzam cümle yapıları kurulur.</p><p>Serimizin 10. bölümünü devirdik aslanım! Böylece isim soylu kelimelerin yapısal süreçlerini tamamladık.</p><p>Serimizin 11. bölümünde, dilimizin en hareketli, en karmaşık ve en zengin motoruna geçiyoruz: <strong>&quot;Fiil Çekim Ekleri (Zamanlar, Kipler ve Şahıs Ekleri)&quot;</strong>.</p><p>Hazırsan sayfayı çevir, devam edelim!</p>',41)])])}const g=e(n,[["render",m]]);export{h as __pageData,g as default};
